namespace Astronomy.MediaFactory.Core.AstronomyDomain.Localization;
public enum LocalizationReviewStatus { Draft, MachineTranslated, HumanReviewed, Approved, Rejected }
public sealed record AstronomyLocalizedContent(string LanguageCode,string DisplayName,string? RegionCode=null,string? ShortName=null,string? Description=null,string? Pronunciation=null,IReadOnlyList<string>? SearchAliases=null,string? CulturalUsageNotes=null,bool IsMachineTranslated=false,string? TranslationSourceId=null,LocalizationReviewStatus ReviewStatus=LocalizationReviewStatus.Draft,string Version="1.0"){ public IReadOnlyList<string> SearchAliases{get;init;}=SearchAliases??[]; public string NormalizedLocale => string.IsNullOrWhiteSpace(RegionCode)?LanguageCode.Trim().ToLowerInvariant():$"{LanguageCode.Trim().ToLowerInvariant()}-{RegionCode.Trim().ToUpperInvariant()}"; }
